\maketitle

\begin{abstract}
Positional numeral systems --- ordinary base-$N$ notation, the factorial number
system (factoradics) used in combinatorics, and the mixed-radix representations
that appear in clocks, calendars, and computer arithmetic --- are traditionally
developed as separate theories. We present a single parameterized theory that
subsumes all of them. Fixing an arbitrary sequence of bases $b_0, b_1, b_2,
\dots$ and the running products $P_k = \prod_{i<k} b_i$, we establish three
foundational facts uniformly: (i)~every valid length-$k$ numeral has value below
$P_k$; (ii)~every integer below $P_k$ is realized by explicit digit extraction
(existence); and (iii)~distinct valid numerals have distinct values (uniqueness).
Combining existence and uniqueness yields a canonical bijection
$\{0,1,\dots,P_k-1\} \cong \prod_{i<k}\{0,\dots,b_i-1\}$, requiring no positivity
hypothesis on the bases. Specializing $b_i = N$ recovers the uniqueness and
existence of standard positional notation; specializing $b_i = i+1$, together with
the telescoping identity $\prod_{i<k}(i+1) = k!$, recovers the factorial number
system and yields the combinatorial count of $k!$ factoradic tuples. The classical
uniqueness theorem for factoradics is derived strictly as a corollary of the
general uniqueness theorem --- a genuine unification rather than a restatement.
\end{abstract}

\section{Introduction}

A positional numeral system encodes an integer as a finite string of digits, each
weighted by a place value. The decimal system weights digits by powers of ten;
binary by powers of two. Less familiar but equally fundamental is the
\emph{factorial number system}, or \emph{factoradic}, in which the $i$-th place has
value $i!$ and the $i$-th digit ranges over $0, \dots, i$. Factoradics are the
natural coordinates for permutations: they underlie the ranking and unranking
algorithms that convert between an arrangement of $k$ objects and an integer in
$\{0, \dots, k! - 1\}$.

These systems are usually presented in isolation, each with its own proofs of the
two properties every place-value system must have: \emph{existence} (every number
in range has a representation) and \emph{uniqueness} (the representation is
one-of-a-kind). We show that all of them are instances of a single
\emph{mixed-radix} theory, and that their foundational theorems are corollaries of
one general result. The unifying device is elementary but powerful: allow the base
to vary from place to place, track the running product of bases, and prove the two
properties once, for all base sequences simultaneously. A notable feature is that
the central bijection is stated and proved with \emph{no} positivity assumption on
the bases: when a base is zero, both sides collapse to the empty set and the
statement holds vacuously.

\section{Definitions}

Throughout, $b : \N \to \N$ is a sequence of \emph{bases} and $k \in \N$ a length.
Digit sequences are functions $c : \N \to \N$; only the first $k$ entries matter
for a length-$k$ numeral.

\begin{definition}[Running product]
The \emph{running product} of the first $k$ bases is
\[ P_k = \rprod(b, k) = \prod_{i<k} b_i, \qquad P_0 = 1, \]
and it satisfies $P_{k+1} = P_k \cdot b_k$.
\end{definition}

\begin{definition}[Value]
The \emph{value} of a digit sequence $c$ over $k$ places is
\[ \val(b, c, k) = \sum_{i<k} c_i \Big( \prod_{j<i} b_j \Big) = \sum_{i<k} c_i\, P_i. \]
\end{definition}

\begin{definition}[Validity]
A digit sequence $c$ is \emph{valid} for $b$ over $k$ places, written
$\Valid(b, c, k)$, if $c_i < b_i$ for all $i < k$.
\end{definition}

\begin{definition}[Digit extraction]
The \emph{digit map} extracts the $i$-th digit of an integer $n$:
\[ \dig(b, n)_i = \Big\lfloor \tfrac{n}{P_i} \Big\rfloor \bmod b_i. \]
\end{definition}

\begin{definition}[Specializations]
The \emph{base-$N$} system is the constant sequence $b_i = N$ (then $P_k = N^k$);
the \emph{factoradic} is $b_i = i + 1$ (then $P_k = k!$, Lemma~\ref{lem:factprod}).
\end{definition}

\section{The telescoping hinge}

\begin{lemma}[Factorial running product]\label{lem:factprod}
For all $k$, $\ \rprod(i \mapsto i+1,\, k) = \prod_{i<k}(i+1) = k!.$
\end{lemma}
\begin{proof}
Induction on $k$. The base case is $P_0 = 1 = 0!$. For the step,
$P_{k+1} = P_k (k+1) = k!\,(k+1) = (k+1)!$. \end{proof}

\begin{lemma}[Base-$N$ running product]\label{lem:baseNprod}
$\rprod(i \mapsto N,\, k) = N^k.$
\end{lemma}
\begin{proof}
Induction: $P_{k+1} = P_k \cdot N = N^k \cdot N = N^{k+1}$. \end{proof}

Lemma~\ref{lem:factprod} is the crux of the unification: the factoradic place
values $P_i = i!$ are exactly the running products, so the factoradic \emph{is} the
mixed-radix system with $b_i = i+1$.

\section{The general theory}

\begin{proposition}[Boundedness]\label{prop:bound}
If $c$ is valid over $k$ places, then $\val(b, c, k) < P_k$.
\end{proposition}
\begin{proof}[Proof sketch]
Induction on $k$. For $k=0$, $0 < 1 = P_0$. For the step,
$\val(b,c,k+1) = \val(b,c,k) + c_k P_k \le (P_k - 1) + (b_k - 1)P_k = P_{k+1} - 1$.
\end{proof}

\begin{proposition}[Existence]\label{prop:exist}
For every $n < P_k$, $\ \val\big(b,\, \dig(b, n),\, k\big) = n.$
\end{proposition}
\begin{proof}[Proof sketch]
Induction on $k$, unwinding the division algorithm
$n = P_k \lfloor n/P_k \rfloor + (n \bmod P_k)$. The low $k$ digits reconstruct
$n \bmod P_k$, and for $n < P_k$ the quotient contributions vanish. Each extracted
digit is reduced modulo its base, hence valid.
\end{proof}

\begin{proposition}[Uniqueness]\label{prop:unique}
If $c$ and $d$ are valid over $k$ places and $\val(b, c, k) = \val(b, d, k)$, then
$c_i = d_i$ for all $i < k$.
\end{proposition}
\begin{proof}[Proof sketch]
Reducing the common value modulo $P_1 = b_0$ isolates $c_0 = d_0$; subtracting and
dividing by $b_0$ reduces to the same problem with $k-1$ places, and induction
finishes. Equivalently, both sequences equal $\dig(b, n)$ for their common value
$n$ by Proposition~\ref{prop:exist}.
\end{proof}

\begin{theorem}[The mixed-radix bijection]\label{thm:bij}
For every base sequence $b$ and length $k$ there is a bijection
\[ \Phi : \{0, 1, \dots, P_k - 1\} \xrightarrow{\ \cong\ } \prod_{i<k} \{0, 1, \dots, b_i - 1\}, \]
onto the set of valid digit tuples. The forward map sends $n$ to $\dig(b, n)$
restricted to $i < k$; the inverse sends a valid tuple $c$ to $\val(b, \bar c, k)$,
where $\bar c$ pads $c$ with zeros beyond place $k$.
\end{theorem}
\begin{proof}[Proof sketch]
Each extracted digit lies in $\{0,\dots,b_i-1\}$, positivity of in-range bases
being forced by $P_k > 0$; the inverse is well defined by
Proposition~\ref{prop:bound}. The two maps are mutually inverse by
Propositions~\ref{prop:exist} and~\ref{prop:unique}. No positivity hypothesis is
needed: if some $b_i = 0$ then $P_k = 0$ and both sides are empty.
\end{proof}

\begin{theorem}[Counting identity]\label{thm:count}
$\ \#\big( \prod_{i<k} \{0,\dots,b_i-1\} \big) = \prod_{i<k} b_i = P_k.$
\end{theorem}
\begin{proof}
The codomain of $\Phi$ has cardinality $\prod_{i<k} b_i$ and is in bijection with
$\{0,\dots,P_k-1\}$ by Theorem~\ref{thm:bij}. \end{proof}

\section{Corollary: ordinary base-$N$ numerals}

\begin{corollary}[Uniqueness]\label{cor:baseNunique}
If $c_i, d_i < N$ for all $i < k$ and $\sum_{i<k} c_i N^i = \sum_{i<k} d_i N^i$,
then $c_i = d_i$ for all $i < k$.
\end{corollary}
\begin{proof} Proposition~\ref{prop:unique} with $b_i = N$. \end{proof}

\begin{corollary}[Existence]
Every $n < N^k$ equals the base-$N$ value of its own extracted digits.
\end{corollary}
\begin{proof} Proposition~\ref{prop:exist} with $b_i = N$ and $P_k = N^k$. \end{proof}

\begin{corollary}[Base-$N$ bijection]
There is a bijection $\{0, 1, \dots, N^k - 1\} \cong \{0, \dots, N-1\}^k.$
\end{corollary}
\begin{proof} Theorem~\ref{thm:bij} with $b_i = N$. \end{proof}

\section{Corollary: the factorial number system}

Two bridge lemmas align the general definitions with the classical factoradic ones.

\begin{lemma}[Value bridge]\label{lem:valbridge}
For $b_i = i + 1$, $\ \val(i \mapsto i+1,\, c,\, k) = \sum_{i<k} c_i \cdot i!.$
\end{lemma}
\begin{proof} The place weight is $P_i = \prod_{j<i}(j+1) = i!$ by
Lemma~\ref{lem:factprod}. \end{proof}

\begin{lemma}[Validity bridge]\label{lem:validbridge}
For $b_i = i+1$, validity coincides with factoradic validity: $c_i < i + 1 \iff c_i \le i.$
\end{lemma}
\begin{proof} The two inequalities are equivalent for natural numbers. \end{proof}

\begin{corollary}[Uniqueness of factoradics, derived]\label{cor:factunique}
If $c_i \le i$ and $d_i \le i$ for all $i < k$ and
$\sum_{i<k} c_i\, i! = \sum_{i<k} d_i\, i!$, then $c_i = d_i$ for all $i < k$.
\end{corollary}
\begin{proof}
Translate through Lemmas~\ref{lem:valbridge} and~\ref{lem:validbridge} into
mixed-radix form for $b_i = i+1$ and apply Proposition~\ref{prop:unique}.
\end{proof}

Corollary~\ref{cor:factunique} is obtained purely from the general
Proposition~\ref{prop:unique}, transported along the bridge lemmas, with no
independent factoradic uniqueness result; the derivation is non-circular.

\begin{corollary}[Factoradic bijection]
There is a bijection
$\{0, 1, \dots, k! - 1\} \cong \prod_{i<k} \{0, \dots, i\}.$
\end{corollary}
\begin{proof} Theorem~\ref{thm:bij} with $b_i = i+1$ and $P_k = k!$. \end{proof}

\begin{corollary}[Factoradic count]
$\ \#\big( \prod_{i<k} \{0, \dots, i\} \big) = k!.$
\end{corollary}
\begin{proof} Theorem~\ref{thm:count} with $b_i = i+1$. \end{proof}

The last identity is the combinatorial punchline: length-$k$ factoradic tuples are
in bijection with a set of size $k!$, matching the number of permutations of $k$
objects.

\section{Algorithms}

\paragraph{Encode (integer $\to$ tuple).} For $n < P_k$: for $i = 0,\dots,k-1$ set
$c_i = n \bmod b_i$ and $n \leftarrow \lfloor n / b_i \rfloor$; return $(c_i)$.
Correctness is Proposition~\ref{prop:exist}; cost $O(k)$.

\paragraph{Decode (tuple $\to$ integer).} By Horner's rule from the top: $n = 0$;
for $i = k-1,\dots,0$ set $n \leftarrow n\,b_i + c_i$; return $n$. Correctness is
the definition of value; cost $O(k)$. The two are exact inverses by
Theorem~\ref{thm:bij}.

\section{Applications and discussion}

The factoradic bijection is the engine of permutation ranking and unranking: a
factoradic tuple with $c_i \le i$ is a Lehmer code, and composing with the
Lehmer-code correspondence gives an explicit order isomorphism between
$\{0,\dots,k!-1\}$ and the $k!$ permutations of a $k$-element set. Timekeeping,
calendars, and byte layouts are all mixed-radix systems whose lossless conversion
is guaranteed by Theorem~\ref{thm:bij} with no per-system proof. Because existence,
uniqueness, and the counting identity are proved once, downstream developments
inherit them for every specialization at once. The deliberate absence of a
positivity hypothesis makes the theory total, absorbing the degenerate case
$b_i = 0$ automatically.

\section{Future directions}

\begin{itemize}
  \item \textbf{Permutation ranking.} Compose the factoradic bijection with the
  Lehmer-code correspondence for an explicit order isomorphism
  $\{0,\dots,k!-1\} \cong \mathrm{Perm}(k)$.
  \item \textbf{Successor dynamics.} Formalize ``add one with carries'' on tuples
  and show it matches $n \mapsto n+1 \pmod{P_k}$.
  \item \textbf{Order.} Prove the bijection is an order isomorphism for the
  appropriate lexicographic order on tuples.
\end{itemize}

\section{Conclusion}

A single mixed-radix theory provides existence, uniqueness, and a counting
identity for every positional system at once. Its central bijection specializes to
ordinary base-$N$ notation and, via $\prod_{i<k}(i+1) = k!$, to the factorial
number system, whose classical uniqueness theorem is recovered strictly as a
corollary. Distinct-looking numeration systems are two windows onto one
parameterized structure.

\end{document}

