from math import factorial, prod

b = lambda i: i + 1
for k in range(1, 9):
    P = prod(b(i) for i in range(k))
    assert P == factorial(k)
    print(f'k={k}: prod (i+1) = {P} = {k}!')

def encode(b, n, k):
    d = []
    for i in range(k):
        d.append(n % b(i)); n //= b(i)
    return tuple(d)

k = 5
tuples = {encode(b, n, k) for n in range(factorial(k))}
print('distinct factoradic tuples for k=5:', len(tuples), '= 5! =', factorial(5))

