function ENCODE(b, n, k):
    c <- empty list
    for i from 0 to k-1:
        c[i] <- n mod b(i)          # extract least significant remaining digit
        n    <- n div b(i)          # shift down by base b(i)
    return (c[0], ..., c[k-1])       # little-endian valid digit tuple

