from math import prod
from typing import Callable, List

def radix_prod(b: Callable[[int], int], k: int) -> int:
    return prod(b(i) for i in range(k))

def encode(b: Callable[[int], int], n: int, k: int) -> List[int]:
    """Integer n < P_k -> unique valid mixed-radix digit tuple."""
    assert 0 <= n < radix_prod(b, k)
    digits: List[int] = []
    for i in range(k):
        digits.append(n % b(i))
        n //= b(i)
    return digits

